import re

PAD, BLANK, EOS = "<pad>", "<blk>", "<eos>"
PUNCTUATION = list(" ,.!?'-")
LETTERS = list("abcdefghijklmnopqrstuvwxyz")

ABBREVIATIONS = {"dr.": "doctor", "mr.": "mister", "mrs.": "missus",
                 "st.": "saint", "no.": "number"}
DIGITS = {"0": "zero", "1": "one", "2": "two", "3": "three", "4": "four",
          "5": "five", "6": "six", "7": "seven", "8": "eight", "9": "nine"}


def say_digits(number):
    return " ".join(DIGITS[digit] for digit in number)


def normalize(text):
    text = text.lower().strip()
    for short, long in ABBREVIATIONS.items():
        text = re.sub(r"\b" + re.escape(short), long, text)
    text = re.sub(r"\$(\d+)", lambda m: say_digits(m.group(1)) + " dollars", text)
    text = re.sub(r"\d+", lambda m: say_digits(m.group(0)), text)
    return re.sub(r"\s+", " ", text).strip()


def build_vocab():
    symbols = [PAD, BLANK, EOS] + PUNCTUATION + LETTERS
    return symbols, {symbol: index for index, symbol in enumerate(symbols)}


def encode(text, stoi):
    ids = [stoi[character] for character in normalize(text) if character in stoi]
    return ids + [stoi[EOS]]


def decode(ids, symbols):
    return "".join(symbols[index] for index in ids)
